DROP TABLE IF EXISTS `cyan_question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cyan_question` (
  `question_id` bigint NOT NULL AUTO_INCREMENT COMMENT '题目ID',
  `category` varchar(50) NOT NULL COMMENT '题目分类（JAVA/PYTHON/C/HTML）',
  `difficulty` tinyint NOT NULL DEFAULT '1' COMMENT '难易程度（1-5）',
  `question_type` varchar(20) NOT NULL COMMENT '题目类型（SINGLE_CHOICE/MULTI_CHOICE/JUDGE/FILL_BLANK/SHORT_ANSWER）',
  `title` text NOT NULL COMMENT '题干',
  `sub_title` text COMMENT '副题干（选择题选项JSON，非选择可空）',
  `answer` text NOT NULL COMMENT '答案',
  `status` char(1) DEFAULT '0' COMMENT '状态（0启用 1停用）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `grading_rules` text,
  `initial_code` text,
  `review_state` varchar(16) NOT NULL DEFAULT 'PUBLISHED',
  `revision` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`question_id`),
  KEY `idx_category` (`category`),
  KEY `idx_type` (`question_type`)
) ENGINE=InnoDB AUTO_INCREMENT=145 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='题库表';
