0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(38,'PYTHON',3,'SINGLE_CHOICE','以下哪个模块用于生成随机数？','[{\"label\":\"A\",\"content\":\"sys\",\"isAnswer\":0},{\"label\":\"B\",\"content\":\"os\",\"isAnswer\":0},{\"label\":\"C\",\"content\":\"random\",\"isAnswer\":1},{\"label\":\"D\",\"content\":\"math\",\"isAnswer\":0}]','C','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(39,'PYTHON',3,'SINGLE_CHOICE','下列代码的输出是：x = 5; def foo(): x = 10; print(x); foo(); print(x)','[{\"label\":\"A\",\"content\":\"10 5\",\"isAnswer\":1},{\"label\":\"B\",\"content\":\"5 10\",\"isAnswer\":0},{\"label\":\"C\",\"content\":\"10 10\",\"isAnswer\":0},{\"label\":\"D\",\"content\":\"报错\",\"isAnswer\":0}]','A','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(40,'PYTHON',3,'SINGLE_CHOICE','下列哪个不是 Python 中的合法标识符？','[{\"label\":\"A\",\"content\":\"_var\",\"isAnswer\":0},{\"label\":\"B\",\"content\":\"var2\",\"isAnswer\":0},{\"label\":\"C\",\"content\":\"2var\",\"isAnswer\":1},{\"label\":\"D\",\"content\":\"var_name\",\"isAnswer\":0}]','C','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(41,'PYTHON',3,'SINGLE_CHOICE','关于字典 d = {\'a\':1, \'b\':2}，以下哪个操作会引发 KeyError？','[{\"label\":\"A\",\"content\":\"d[\'a\']\",\"isAnswer\":0},{\"label\":\"B\",\"content\":\"d.get(\'c\')\",\"isAnswer\":0},{\"label\":\"C\",\"content\":\"d[\'c\']\",\"isAnswer\":1},{\"label\":\"D\",\"content\":\"d.get(\'a\')\",\"isAnswer\":0}]','C','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(42,'PYTHON',3,'FILL_BLANK','在 Python 中，获取用户输入的函数是 ________，将字符串转换为整数的函数是 ________。','','input();int()','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(43,'PYTHON',3,'FILL_BLANK','表达式 len([1,2,3] + [4,5]) 的值为 ________。','','5','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(44,'PYTHON',3,'FILL_BLANK','已知 t = (1,2,3)，执行 t[1] = 10 会引发 ________ 异常，因为元组是 ________（填“可变”或“不可变”）类型。','','TypeError;不可变','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(45,'PYTHON',3,'FILL_BLANK','下列代码的运行结果是 ________。for i in range(3): print(i, end=\' \'); else: print(\"done\")','','0 1 2 done','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(46,'PYTHON',3,'FILL_BLANK','表达式 [x**2 for x in range(3)] 的值为 ________。','','[0, 1, 4]','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(47,'PYTHON',3,'SHORT_ANSWER','阅读程序并写出输出结果：def func(a, b=[]): b.append(a); return b; print(func(1)); print(func(2)); print(func(3, [])); print(func(4))','','[1]\n[1, 2]\n[3]\n[1, 2, 4]','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(48,'PYTHON',3,'SHORT_ANSWER','阅读程序并写出输出结果：s = \"Python123\"; result = \"\"; for ch in s: if ch.isalpha(): result += ch.upper(); elif ch.isdigit(): result += str(int(ch) * 2); else: result += ch; print(result)','','PYTHON246','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(49,'PYTHON',3,'SHORT_ANSWER','编写一个函数 is_palindrome(s)，判断字符串 s 是否为回文（忽略大小写和非字母数字字符）。例如：\"A man, a plan, a canal: Panama\" 应返回 True；\"race a car\" 应返回 False。在函数体内实现逻辑，并编写简短测试代码输出结果。','','def is_palindrome(s): cleaned = \'\'.join(ch.lower() for ch in s if ch.isalnum()); return cleaned == cleaned[::-1]; print(is_palindrome(\"A man, a plan, a canal: Panama\")); print(is_palindrome(\"race a car\"))','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(50,'PYTHON',3,'SHORT_ANSWER','编写一个程序，生成一个 1~100 之间的随机整数，让用户猜这个数字。要求：每次猜错时提示“猜大了”或“猜小了”；猜中时输出“恭喜！猜了 X 次”，并结束游戏；用户输入非数字时应提示“请输入合法数字”。（使用 random 模块）','','import random; target = random.randint(1, 100); count = 0; while True: try: guess = input(\"猜一个1~100之间的整数: \"); num = int(guess); count += 1; if num < target: print(\"猜小了\"); elif num > target: print(\"猜大了\"); else: print(f\"恭喜！猜了{count}次\"); break; except ValueError: print(\"请输入合法数字\")','0','',NULL,'',NULL,NULL,NULL,NULL,'PUBLISHED',1),(70,'PYTHON',1,'PYTHON','两数之和','从标准输入读取一行，包含两个整数 a 和 b（-10^9 <= a,b <= 10^9），以空格分隔。输出 a+b，末尾换行。示例输入：3 5；示例输出：8。','{\"cases\": [{\"input\": \"3 5\\n\", \"public\": true, \"weight\": 0, \"expected\": \"8\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"-8 3\\n\", \"public\": false, \"weight\": 3, \"expected\": \"-5\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"0 0\\n\", \"public\": false, \"weight\": 3, \"expected\": \"0\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"1000000000 999999999\\n\", \"public\": false, \"weight\": 4, \"expected\": \"1999999999\\n\", \"comparison\": \"EXACT\"}]}','0','',NULL,'',NULL,'Python练习:20261030:01',NULL,'a, b = map(int, input().split())\n# 输出两数之和\n','PUBLISHED',1),(71,'PYTHON',1,'PYTHON','偶数之和','第一行输入整数 n（1 <= n <= 1000），第二行输入 n 个整数（每个绝对值不超过 10^6）。输出其中所有偶数的和；没有偶数时输出 0。结果末尾换行。示例输入：第一行 5，第二行 1 2 3 4 6；示例输出：12。','{\"cases\": [{\"input\": \"5\\n1 2 3 4 6\\n\", \"public\": true, \"weight\": 0, \"expected\": \"12\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"4\\n-2 -3 0 7\\n\", \"public\": false, \"weight\": 3, \"expected\": \"-2\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"1\\n9\\n\", \"public\": false, \"weight\": 3, \"expected\": \"0\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"6\\n10 11 12 13 14 15\\n\", \"public\": false, \"weight\": 4, \"expected\": \"36\\n\", \"comparison\": \"EXACT\"}]}','0','',NULL,'',NULL,'Python练习:20261030:02',NULL,'n = int(input())\nnumbers = list(map(int, input().split()))\n# 只计算偶数的和\n','PUBLISHED',1),(72,'PYTHON',2,'PYTHON','单词出现次数','第一行是一段由单个空格分隔的单词（1 到 1000 个），第二行是要查找的单词。单词只包含大小写英文字母，严格区分大小写。输出该单词在第一行中出现的次数，末尾换行。示例输入：第一行 apple banana apple pear apple，第二行 apple；示例输出：3。','{\"cases\": [{\"input\": \"apple banana apple pear apple\\napple\\n\", \"public\": true, \"weight\": 0, \"expected\": \"3\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"red blue red\\ngreen\\n\", \"public\": false, \"weight\": 3, \"expected\": \"0\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"Hi hi Hi\\nHi\\n\", \"public\": false, \"weight\": 3, \"expected\": \"2\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"x\\nx\\n\", \"public\": false, \"weight\": 4, \"expected\": \"1\\n\", \"comparison\": \"EXACT\"}]}','0','',NULL,'',NULL,'Python练习:20261030:03',NULL,'words = input().split()\ntarget = input().strip()\n# 输出目标单词出现的次数（区分大小写）\n','PUBLISHED',1),(73,'PYTHON',3,'PYTHON','最长连续严格递增段','第一行输入整数 n（1 <= n <= 1000），第二行输入 n 个整数（每个绝对值不超过 10^6）。求相邻元素严格递增的最长连续段长度；相等不算递增。输出长度，末尾换行。示例输入：第一行 7，第二行 1 2 3 2 4 5 6；示例输出：4。','{\"cases\": [{\"input\": \"7\\n1 2 3 2 4 5 6\\n\", \"public\": true, \"weight\": 0, \"expected\": \"4\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"1\\n42\\n\", \"public\": false, \"weight\": 3, \"expected\": \"1\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"5\\n5 6 6 6 6\\n\", \"public\": false, \"weight\": 3, \"expected\": \"2\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"8\\n-3 -2 0 1 0 1 2 3\\n\", \"public\": false, \"weight\": 4, \"expected\": \"4\\n\", \"comparison\": \"EXACT\"}]}','0','',NULL,'',NULL,'Python练习:20261030:04',NULL,'n = int(input())\nnumbers = list(map(int, input().split()))\n# 求最长连续严格递增段的长度\n','PUBLISHED',1),(74,'PYTHON',2,'SINGLE_CHOICE','Python 中用于定义代码块的方式是什么？','[{\"label\": \"A\", \"content\": \"使用大括号 {}\", \"isAnswer\": 0}, {\"label\": \"B\", \"content\": \"使用缩进\", \"isAnswer\": 1}, {\"label\": \"C\", \"content\": \"使用分号 ;\", \"isAnswer\": 0}, {\"label\": \"D\", \"content\": \"使用圆括号 ()\", \"isAnswer\": 0}]','B','0','',NULL,'',NULL,'模拟卷:A:单选:01；来源：A单选1',NULL,NULL,'PUBLISHED',1),(75,'PYTHON',2,'SINGLE_CHOICE','以下哪个不是 Python 的合法注释方式？','[{\"label\": \"A\", \"content\": \"#\", \"isAnswer\": 0}, {\"label\": \"B\", \"content\": \"\'\'\'\", \"isAnswer\": 0}, {\"label\": \"C\", \"content\": \"//\", \"isAnswer\": 1}, {\"label\": \"D\", \"content\": \"\\\"\\\"\\\"\", \"isAnswer\": 0}]','C','0','',NULL,'',NULL,'模拟卷:A:单选:02；来源：A单选2',NULL,NULL,'PUBLISHED',1),(76,'PYTHON',2,'SINGLE_CHOICE','下列选项中，哪个是合法的变量名？','[{\"label\": \"A\", \"content\": \"3_data\", \"isAnswer\": 0}, {\"label\": \"B\", \"content\": \"_data\", \"isAnswer\": 1}, {\"label\": \"C\", \"content\": \"data - 3\", \"isAnswer\": 0}, {\"label\": \"D\", \"content\": \"and\", \"isAnswer\": 0}]','B','0','',NULL,'',NULL,'模拟卷:A:单选:03；来源：A单选3',NULL,NULL,'PUBLISHED',1),(77,'PYTHON',2,'SINGLE_CHOICE','使用 input() 函数获取用户输入时，返回的数据类型是什么？','[{\"label