INSERT INTO `exam_onsite_event` VALUES (87,40,NULL,1,'CREATE','创建现场任务','{\"description\":\"2.（中等题，满分20分） 请编写一段代码完成“电量巡航任务”：\\n(1)设定一个无限循环（while True），并导入time模块。（4分）\\n(2)每次循环开始时读取机器人的电量数值。（4分）\\n(3)编写if...else判断结构：如果获取到的电量大于 20，语音播报“电量充足”，并将胸口灯效（type设为\\\"button\\\"）设置为绿色（\\\"green\\\"），模式为常亮（\\\"solid\\\"），然后退出整个循环（使用 break）。（4分）\\n(4) 如果电量小于或等于 20，语音播报“需要充电”。（4分）\\n(5) 在电量不足分支内，将胸口灯效设置为红色（\\\"red\\\"），模式为闪烁（\\\"blink\\\"），并让程序睡眠等待 5 秒。（4分）\",\"durationMinutes\":10,\"items\":[{\"maxScore\":4,\"title\":\"设定一个无限循环（while True），并导入time模块。\"},{\"maxScore\":4,\"title\":\"每次循环开始时读取机器人的电量数值。\"},{\"maxScore\":4,\"title\":\"编写if...else判断结构：如果获取到的电量大于 20，语音播报“电量充足”，并将胸口灯效（type设为\\\"button\\\"）设置为绿色（\\\"green\\\"），模式为常亮（\\\"solid\\\"），然后退出整个循环（使用 break）。\"},{\"maxScore\":4,\"title\":\"如果电量小于或等于 20，语音播报“需要充电”。\"},{\"maxScore\":4,\"title\":\"在电量不足分支内，将胸口灯效设置为红色（\\\"red\\\"），模式为闪烁（\\\"blink\\\"），并让程序睡眠等待 5 秒。\"}],\"title\":\"电量巡航任务\"}','2026-10-30 02:34:58.319'),(88,41,NULL,1,'CREATE','创建现场任务','{\"description\":\"3.（困难题，满分25分） 请编写一段代码完成“才艺展示任务”：\\n(1)语音播报“请下达才艺指令”。（3分）\\n(2)执行一次语义理解提取结果（使用 sync_do_voice_asr_value() ），将获取到的文本保存在 asr_result 变量中。（4分）\\n(3)编写if...elif...else结构对文本内容进行多分支判断。（4分）\\n(4)如果指令包含“唱歌”，则异步播放音乐“我和我的祖国.mp3”。（4分）\\n(5)如果指令包含“俯卧撑”，则异步执行动作“PushUp”。（4分）\\n(6) 如果指令包含“站起来”，则异步执行动作“GetUp”。（3分）\\n(7) 其他情况，播报“该才艺尚未学习”，并在所有条件判断完全结束后播报“才艺展示结束”。（3分）\",\"durationMinutes\":10,\"items\":[{\"maxScore\":3,\"title\":\"语音播报“请下达才艺指令”。\"},{\"maxScore\":4,\"title\":\"执行一次语义理解提取结果（使用 sync_do_voice_asr_value() ），将获取到的文本保存在 asr_result 变量中。\"},{\"maxScore\":4,\"title\":\"编写if...elif...else结构对文本内容进行多分支判断。\"},{\"maxScore\":4,\"title\":\"如果指令包含“唱歌”，则异步播放音乐“我和我的祖国.mp3”。\"},{\"maxScore\":4,\"title\":\"如果指令包含“俯卧撑”，则异步执行动作“PushUp”。\"},{\"maxScore\":3,\"title\":\"如果指令包含“站起来”，则异步执行动作“GetUp”。\"},{\"maxScore\":3,\"title\":\"其他情况，播报“该才艺尚未学习”，并在所有条件判断完全结束后播报“才艺展示结束”。\"}],\"title\":\"才艺展示任务\"}','2026-10-30 02:34:58.374'),(89,41,105,105,'CODE_SUBMIT','提交机器人实操代码','{\"sourceHash\":\"adfa124aad5d588c302be