INSERT INTO `exam_question_snapshot` VALUES (92070,32,0,'PYTHON',3,'SINGLE_CHOICE','以下哪个关键字用于在 Python 中定义函数？','[{\"label\":\"A\",\"content\":\"func\",\"isAnswer\":0},{\"label\":\"B\",\"content\":\"def\",\"isAnswer\":1},{\"label\":\"C\",\"content\":\"define\",\"isAnswer\":0},{\"label\":\"D\",\"content\":\"lambda\",\"isAnswer\":0}]','B',10,NULL,NULL),(92070,33,1,'PYTHON',3,'SINGLE_CHOICE','下列哪个数据是 不可变 的？','[{\"label\":\"A\",\"content\":\"列表\",\"isAnswer\":0},{\"label\":\"B\",\"content\":\"字典\",\"isAnswer\":0},{\"label\":\"C\",\"content\":\"元组\",\"isAnswer\":1},{\"label\":\"D\",\"content\":\"集合\",\"isAnswer\":0}]','C',10,NULL,NULL),(92070,70,2,'PYTHON',1,'PYTHON','两数之和','从标准输入读取一行，包含两个整数 a 和 b（-10^9 <= a,b <= 10^9），以空格分隔。输出 a+b，末尾换行。示例输入：3 5；示例输出：8。','{\"cases\": [{\"input\": \"3 5\\n\", \"public\": true, \"weight\": 0, \"expected\": \"8\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"-8 3\\n\", \"public\": false, \"weight\": 3, \"expected\": \"-5\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"0 0\\n\", \"public\": false, \"weight\": 3, \"expected\": \"0\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"1000000000 999999999\\n\", \"public\": false, \"weight\": 4, \"expected\": \"1999999999\\n\", \"comparison\": \"EXACT\"}]}',10,NULL,'a, b = map(int, input().split())\n# 输出两数之和\n'),(92070,71,3,'PYTHON',1,'PYTHON','偶数之和','第一行输入整数 n（1 <= n <= 1000），第二行输入 n 个整数（每个绝对值不超过 10^6）。输出其中所有偶数的和；没有偶数时输出 0。结果末尾换行。示例输入：第一行 5，第二行 1 2 3 4 6；示例输出：12。','{\"cases\": [{\"input\": \"5\\n1 2 3 4 6\\n\", \"public\": true, \"weight\": 0, \"expected\": \"12\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"4\\n-2 -3 0 7\\n\", \"public\": false, \"weight\": 3, \"expected\": \"-2\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"1\\n9\\n\", \"public\": false, \"weight\": 3, \"expected\": \"0\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"6\\n10 11 12 13 14 15\\n\", \"public\": false, \"weight\": 4, \"expected\": \"36\\n\", \"comparison\": \"EXACT\"}]}',10,NULL,'n = int(input())\nnumbers = list(map(int, input().split()))\n# 只计算偶数的和\n'),(92072,71,0,'PYTHON',1,'PYTHON','偶数之和','第一行输入整数 n（1 <= n <= 1000），第二行输入 n 个整数（每个绝对值不超过 10^6）。输出其中所有偶数的和；没有偶数时输出 0。结果末尾换行。示例输入：第一行 5，第二行 1 2 3 4 6；示例输出：12。','{\"cases\": [{\"input\": \"5\\n1 2 3 4 6\\n\", \"public\": true, \"weight\": 0, \"expected\": \"12\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"4\\n-2 -3 0 7\\n\", \"public\": false, \"weight\": 3, \"expected\": \"-2\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"1\\n9\\n\", \"public\": false, \"weight\": 3, \"expected\": \"0\\n\", \"comparison\": \"EXACT\"}, {\"input\": \"6\\n10 11 12 13 14 15\\n\", \"public\": false, \"weight\": 4, \"expected\": \"36\\n\", \"comparison\": \"EXACT\"}]}',10,NULL,'n = int(input())\nnumbers = list(map(int, input().split()))\n# 只计算偶数的和\n');
